export const dynamic = "force-dynamic";

export default function Home() {
  const serverTimestamp = new Date().toLocaleString();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>Current server time: <strong>{serverTimestamp}</strong></p>
      <p>This timestamp changes on every request (not prerendered at build time).</p>
    </main>
  );
}

